56: impl Player {
57:     pub fn new(duration: f64, fps: f64) -> Player {
58:         Player { duration: if duration.is_finite() { duration.max(0.0) } else { 0.0 }, fps: if fps.is_finite() && fps > 1.0 && fps < 480.0 { fps } else { 25.0 }, ..Player::default() }
