65:     pub fn clamp_pos(&self, t: f64) -> f64 {
66:         if !t.is_finite() {
67:             return 0.0;
68:         }
69:         if self.duration > 0.0 {
70:             t.clamp(0.0, (self.duration - 0.001).max(0.0))
71:         } else {
72:             t.max(0.0)
73:         }
74:     }
75: 
76:     pub fn fraction(&self) -> f64 {
77:         if self.duration > 0.0 {
78:             (self.position / self.duration).clamp(0.0, 1.0)
79:         } else {
80:             0.0
81:         }
82:     }
