493: /// Number keys 1..9 seek to 10%..90%, like YouTube. Returned separately since they are one binding family.
494: pub fn lookup(bindings: &[Binding], key: &str, ctrl: bool, shift: bool, alt: bool) -> Option<Cmd> {
495:     if !ctrl && !alt && key.len() == 1 && key.as_bytes()[0].is_ascii_digit() && key != "0" && key != "9" {
496:         return Some(Cmd::SeekFrac(key.as_bytes()[0] - b'0'));
497:     }
498:     bindings.iter().find(|x| x.key == key && x.ctrl == ctrl && x.shift == shift && x.alt == alt).map(|x| x.cmd)
499: }
