501: impl Player {
502:     /// Applies a command that only touches playback state. UI-level commands (fullscreen, playlist, tracks…)
503:     /// are returned unchanged for the host to handle.
504:     pub fn apply(&mut self, cmd: Cmd) -> (Vec<Event>, Option<Cmd>) {
505:         let ev = match cmd {
506:             Cmd::TogglePause => self.toggle_pause(),
507:             Cmd::SeekRel(d) => self.seek_rel(d),
508:             Cmd::SeekStart => self.seek_abs(0.0),
509:             Cmd::SeekFrac(n) => self.seek_frac(n as f64 / 10.0),
510:             Cmd::FrameStep(d) => self.frame_step(d),
511:             Cmd::SpeedScale(f) => self.speed_scale(f),
512:             Cmd::SpeedStep(u) => self.speed_step(u),
513:             Cmd::SpeedReset => self.set_speed(1.0),
514:             Cmd::VolumeStep(d) => self.volume_step(d),
515:             Cmd::ToggleMute => self.toggle_mute(),
516:             Cmd::LoopAb => {
517:                 self.cycle_ab();
518:                 vec![Event::Osd]
519:             }
520:             Cmd::LoopFile => {
521:                 self.toggle_loop_file();
522:                 vec![Event::Osd]
523:             }
524:             Cmd::NextChapter => self.next_chapter(),
525:             Cmd::PrevChapter => self.prev_chapter(),
526:             Cmd::AudioDelay(d) => {
527:                 self.audio_delay = ((self.audio_delay + d) * 1000.0).round() / 1000.0;
528:                 let m = format!("Audio delay {:+.0} ms", self.audio_delay * 1000.0);
529:                 self.say(m);
530:                 vec![Event::Osd]
531:             }
532:             other => return (vec![], Some(other)),
533:         };
534:         (ev, None)
535:     }
536: }
