276: impl TestCard {
277:     pub fn new(title: &str, duration: f64) -> TestCard {
278:         let (w, h, fps) = (480usize, 270usize, 30.0);
279:         let info = MediaInfo { title: title.into(), container: "testcard".into(), duration, video: vec![VideoStream { index: 0, codec: "procedural".into(), width: w as u32, height: h as u32, fps, bitrate: None, pix_fmt: "rgba".into() }], chapters: vec![(0.0, "Intro".into()), (duration * 0.35, "Middle".into()), (duration * 0.7, "Finale".into())], ..Default::default() };
280:         TestCard { info, w, h, last: None, fps }
281:     }
