306: #[cfg(not(target_arch = "wasm32"))]
307: pub mod ffmpeg {
308:     use super::*;
309:     use std::io::Read;
310:     use std::process::{Child, Command, Stdio};
311:     use std::sync::atomic::{AtomicBool, Ordering};
312:     use std::sync::mpsc::{sync_channel, Receiver};
313:     use std::sync::Arc;
314: 
315:     pub fn available() -> bool {
316:         Command::new("ffmpeg").arg("-version").stdout(Stdio::null()).stderr(Stdio::null()).status().map(|s| s.success()).unwrap_or(false)
317:     }
318: 
319:     pub fn probe(path: &str) -> Result<MediaInfo, String> {
320:         let out = Command::new("ffprobe")
321:             .args(["-v", "error", "-print_format", "json", "-show_format", "-show_streams", "-show_chapters", "--", path])
322:             .stdin(Stdio::null())
323:             .output()
324:             .map_err(|e| format!("ffprobe is not installed ({e})"))?;
325:         if !out.status.success() {
326:             let err = String::from_utf8_lossy(&out.stderr);
327:             return Err(format!("not a playable media file: {}", err.lines().next().unwrap_or("unknown error")));
328:         }
329:         let mut info = parse_ffprobe(&String::from_utf8_lossy(&out.stdout))?;
330:         if info.title.is_empty() {
331:             info.title = path.rsplit('/').next().unwrap_or(path).to_string();
332:         }
333:         Ok(info)
334:     }
335: 
336:     /// `atempo` only accepts 0.5–2.0 per instance, so chain them.
337:     pub fn atempo_chain(speed: f64) -> String {
338:         let mut s = speed.clamp(0.25, 8.0);
339:         let mut parts = vec![];
340:         while s > 2.0 {
341:             parts.push("atempo=2.0".to_string());
342:             s /= 2.0;
343:         }
344:         while s < 0.5 {
345:             parts.push("atempo=0.5".to_string());
346:             s /= 0.5;
347:         }
348:         parts.push(format!("atempo={s:.4}"));
349:         parts.join(",")
350:     }
351: 
352:     pub fn video_args(path: &str, start: f64, w: u32, h: u32) -> Vec<String> {
353:         let mut a: Vec<String> = ["-hide_banner", "-loglevel", "error", "-nostdin", "-hwaccel", "auto"].iter().map(|s| s.to_string()).collect();
354:         a.extend(["-ss".into(), format!("{:.3}", start.max(0.0)), "-i".into(), path.into(), "-an".into(), "-sn".into(), "-vf".into(), format!("scale={w}:{h}:flags=fast_bilinear"), "-pix_fmt".into(), "rgba".into(), "-f".into(), "rawvideo".into(), "-".into()]);
355:         a
356:     }
357: 
358:     /// Interleaved stereo f32le at 48 kHz.
359:     pub fn audio_args(path: &str, start: f64, audio_n: usize, speed: f64) -> Vec<String> {
360:         let mut a: Vec<String> = ["-hide_banner", "-loglevel", "error", "-nostdin"].iter().map(|s| s.to_string()).collect();
361:         a.extend(["-ss".into(), format!("{:.3}", start.max(0.0)), "-i".into(), path.into(), "-map".into(), format!("0:a:{audio_n}"), "-vn".into(), "-sn".into()]);
362:         if (speed - 1.0).abs() > 1e-3 {
363:             a.extend(["-af".into(), atempo_chain(speed)]);
364:         }
365:         a.extend(["-ac".into(), "2".into(), "-ar".into(), "48000".into(), "-f".into(), "f32le".into(), "-".into()]);
366:         a
367:     }
368: 
369:     pub fn sub_args(path: &str, sub_n: usize) -> Vec<String> {
370:         ["-hide_banner", "-loglevel", "error", "-nostdin", "-i", path, "-map", &format!("0:s:{sub_n}"), "-f", "srt", "-"].iter().map(|s| s.to_string()).collect()
371:     }
372: 
373:     /// Extracts an embedded text subtitle track as SRT.
374:     pub fn extract_sub(path: &str, sub_n: usize) -> Result<String, String> {
375:         let out = Command::new("ffmpeg").args(sub_args(path, sub_n)).stdin(Stdio::null()).output().map_err(|e| e.to_string())?;
376:         if !out.status.success() {
377:             return Err("could not extract that subtitle track".into());
378:         }
379:         Ok(String::from_utf8_lossy(&out.stdout).into_owned())
380:     }
381: 
382:     pub struct FfmpegSource {
383:         info: MediaInfo,
384:         path: String,
385:         child: Option<Child>,
386:         rx: Option<Receiver<Frame>>,
387:         pending: Option<Frame>,
388:         w: u32,
389:         h: u32,
390:         done: Arc<AtomicBool>,
391:     }
392: 
393:     impl FfmpegSource {
394:         pub fn open(path: &str, info: MediaInfo, max_w: u32, max_h: u32) -> Result<FfmpegSource, String> {
395:             let (sw, sh) = info.size_wh();
396:             if sw == 0 || sh == 0 {
397:                 return Err("this file has no video stream".into());
398:             }
399:             let (w, h) = fit_size(sw, sh, max_w, max_h);
400:             let mut s = FfmpegSource { info, path: path.into(), child: None, rx: None, pending: None, w, h, done: Arc::new(AtomicBool::new(false)) };
401:             s.spawn(0.0)?;
402:             Ok(s)
403:         }
404: 
405:         fn kill(&mut self) {
406:             self.rx = None; // unblocks the reader thread's send()
407:             if let Some(mut c) = self.child.take() {
408:                 let _ = c.kill();
409:                 let _ = c.wait();
410:             }
411:             self.pending = None;
412:         }
413: 
414:         fn spawn(&mut self, start: f64) -> Result<(), String> {
415:             self.kill();
416:             let mut child = Command::new("ffmpeg").args(video_args(&self.path, start, self.w, self.h)).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().map_err(|e| format!("ffmpeg is not installed ({e})"))?;
417:             let mut out = child.stdout.take().ok_or("no pipe")?;
418:             let (tx, rx) = sync_channel::<Frame>(4);
419:             let (w, h, fps) = (self.w as usize, self.h as usize, self.info.fps());
420:             let done = Arc::new(AtomicBool::new(false));
421:             self.done = done.clone();
422:             std::thread::spawn(move || {
423:                 let mut n = 0u64;
424:                 loop {
425:                     let mut buf = vec![0u8; w * h * 4];
426:                     if out.read_exact(&mut buf).is_err() {
427:                         break;
428:                     }
429:                     let f = Frame { w, h, rgba: buf, pts: start + n as f64 / fps };
430:                     n += 1;
431:                     if tx.send(f).is_err() {
432:                         return;
433:                     }
434:                 }
435:                 done.store(true, Ordering::SeqCst);
436:             });
437:             self.child = Some(child);
438:             self.rx = Some(rx);
439:             Ok(())
440:         }
441:     }
442: 
443:     impl FrameSource for FfmpegSource {
444:         fn info(&self) -> &MediaInfo {
445:             &self.info
446:         }
447:         fn seek(&mut self, t: f64) {
448:             let _ = self.spawn(t);
449:         }
450:         fn poll(&mut self, clock: f64) -> Option<Frame> {
451:             let mut best = None;
452:             if let Some(p) = self.pending.take() {
453:                 if p.pts <= clock {
454:                     best = Some(p);
455:                 } else {
456:                     self.pending = Some(p);
457:                     return None;
458:                 }
459:             }
460:             if let Some(rx) = &self.rx {
461:                 while let Ok(f) = rx.try_recv() {
462:                     if f.pts <= clock {
463:                         best = Some(f);
464:                     } else {
465:                         self.pending = Some(f);
466:                         break;
467:                     }
468:                 }
469:             }
470:             best
471:         }
472:         fn name(&self) -> &'static str {
473:             "ffmpeg"
474:         }
475:         fn exhausted(&self) -> bool {
476:             self.done.load(Ordering::SeqCst) && self.pending.is_none() && self.rx.as_ref().map(|r| r.try_recv().is_err()).unwrap_or(true)
477:         }
478:     }
479: 
480:     impl Drop for FfmpegSource {
481:         fn drop(&mut self) {
482:             self.kill();
483:         }
484:     }
485: 
486:     /// Streams decoded audio in ~100 ms chunks. The host appends each chunk to its output device.
487:     pub struct AudioPipe {
488:         child: Child,
489:         rx: Receiver<Vec<f32>>,
490:     }
491: 
492:     impl AudioPipe {
493:         pub fn open(path: &str, start: f64, audio_n: usize, speed: f64) -> Result<AudioPipe, String> {
494:             let mut child = Command::new("ffmpeg").args(audio_args(path, start, audio_n, speed)).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().map_err(|e| e.to_string())?;
495:             let mut out = child.stdout.take().ok_or("no pipe")?;
496:             let (tx, rx) = sync_channel::<Vec<f32>>(24);
497:             std::thread::spawn(move || {
498:                 let mut raw = vec![0u8; 48_000 / 10 * 2 * 4];
499:                 while out.read_exact(&mut raw).is_ok() {
500:                     let v: Vec<f32> = raw.chunks_exact(4).map(|b| f32::from_le_bytes([b[0], b[1], b[2], b[3]])).collect();
501:                     if tx.send(v).is_err() {
502:                         return;
503:                     }
504:                 }
505:             });
506:             Ok(AudioPipe { child, rx })
507:         }
508:         pub fn try_chunk(&self) -> Option<Vec<f32>> {
509:             self.rx.try_recv().ok()
510:         }
511:     }
512: 
513:     impl Drop for AudioPipe {
514:         fn drop(&mut self) {
515:             let _ = self.child.kill();
516:             let _ = self.child.wait();
517:         }
518:     }
519: }
