253: /// "Movie.en.srt" → "en"; "Movie.srt" → "".
254: pub fn guess_lang(file: &str) -> String {
255:     let stem = file.rsplit_once('.').map(|x| x.0).unwrap_or(file);
256:     match stem.rsplit_once('.') {
257:         Some((_, l)) if (2..=3).contains(&l.len()) && l.chars().all(|c| c.is_ascii_alphabetic()) => l.to_ascii_lowercase(),
258:         _ => String::new(),
259:     }
260: }
