262: /// Sibling subtitle files for `video` out of `names`: same stem (case-insensitive), ext srt/vtt/ass/ssa.
263: pub fn find_sidecars(video: &str, names: &[String]) -> Vec<String> {
264:     let stem = video.rsplit_once('.').map(|x| x.0).unwrap_or(video).to_lowercase();
265:     let mut v: Vec<String> = names
266:         .iter()
267:         .filter(|n| {
268:             let l = n.to_lowercase();
269:             let Some((s, e)) = l.rsplit_once('.') else { return false };
270:             matches!(e, "srt" | "vtt" | "ass" | "ssa") && (s == stem || s.starts_with(&format!("{stem}.")))
271:         })
272:         .cloned()
273:         .collect();
274:     v.sort();
275:     v
276: }
