217:             "list" => self.shell.eiga.show_list = !self.shell.eiga.show_list,
218:             "settings" => self.shell.settings = Some((crate::shell::AppId::Video, 0)),
219:             "remove" => {
220:                 if let Ok(i) = arg.parse::<usize>() {
221:                     let (was_cur, next) = {
222:                         let e = &mut self.shell.eiga;
223:                         let was_cur = e.playlist.cur == Some(i);
224:                         e.playlist.remove(i);
225:                         e.locs.remove(i.min(e.locs.len().saturating_sub(1)));
226:                         let next = if was_cur { e.playlist.cur } else { None };
227:                         if !was_cur {
228:                             if let Some(c) = e.playlist.cur {
229:                                 e.playlist.cur = Some(c.min(e.locs.len().saturating_sub(1)));
230:                             }
231:                         }
232:                         (was_cur, next)
233:                     };
234:                     if was_cur {
235:                         match next {
236:                             Some(n) => self.eiga_play_index(n),
237:                             None => {
238:                                 self.eiga_cleanup();
239:                                 self.shell.eiga.title.clear();
240:                             }
241:                         }
242:                     }
243:                 }
244:             }
