            let mut v = std::mem::take(&mut self.acts);
            v.extend(chrome::ACTS.with(|q| std::mem::take(&mut *q.borrow_mut())));
            if v.is_empty() {
                break;
            }
            for a in v {
                match &a {
                    Act::Toast(t) if t == "\u{1}" => self.drag = None,
                    Act::Toast(t) if t.is_empty() || t == "\u{0}" => {}
                    _ => self.act(a),
                }
