/// Drive gauge colours: accent, then amber from 80 %, then red from 90 %.
pub fn usage_colors(th: &Theme, used: f32) -> (Color32, Color32) {
    if used >= 0.90 {
        (mix(th.danger, Color32::WHITE, 0.22), th.danger)
    } else if used >= 0.80 {
        (mix(th.warn, Color32::WHITE, 0.22), th.warn)
    } else {
        th.accent_grad()
    }
}

