        self.ico(&p, icon, Ic::Filled, orb.center(), 19.0, th.on_accent());
        p.text(pos2(orb.right() + 13.0, orb.center().y - 8.0), Align2::LEFT_CENTER, self.fit(&p, title, &f_bold(T_TITLE), card.width() - 140.0), f_bold(T_TITLE), th.ink1);
        p.text(pos2(orb.right() + 13.0, orb.center().y + 9.0), Align2::LEFT_CENTER, self.fit(&p, sub, &f_medium(T_META), card.width() - 140.0), f_medium(T_META), th.ink3);
        if close {
            // the close control lives in the corner (breaking the header row on purpose) so the title block keeps its own rhythm
            let c = Rect::from_center_size(pos2(card.right() - 20.0, card.top() + 20.0), vec2(26.0, 26.0));
            let r = self.hit(ui, c, "modal-close", Sense::click());
            let a = self.anim(ui, "modal-close-h", r.hovered());
            if a > 0.01 {
                p.circle_filled(c.center(), 13.0 * (0.85 + 0.15 * a), alpha(th.ink3, 0.16 * a));
            }
            self.ico(&p, "close-circle", if r.hovered() { Ic::Filled } else { Ic::Duo }, c.center(), 17.0 + 1.5 * a, mix(th.ink3, th.ink1, a));
            return r.clicked();
        }
        false
    }

